import {
	AlertCircle,
	CheckCircle2,
	ChevronLeft,
	ChevronRight,
	ExternalLink,
} from "lucide-react";
import { type FC, type ReactNode, useState } from "react";
import {
	type InteractionAction,
	InteractionCard,
	type InteractionView,
} from "@/components/agents/interaction-card";
import { Button } from "@/components/ui/button";
import { cn, FILLED_BOX } from "@/lib/utils";
import {
	isExternalHttpUrl,
	isLobuView,
	isServerAuthoredLobuView,
} from "../_shared/view";
import { type McpJsonNode, McpJsonTemplateView } from "./json-template-view";
import { McpMarkdownText } from "./markdown-view";

type UnknownRecord = Record<string, unknown>;

function isRecord(value: unknown): value is UnknownRecord {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function humanize(value: string): string {
	return value
		.replace(/[_-]+/g, " ")
		.replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function stringify(value: unknown): string {
	try {
		return JSON.stringify(value, null, 2);
	} catch {
		return String(value);
	}
}

function compactValue(value: unknown): string {
	if (value === null) return "null";
	if (value === undefined) return "—";
	if (typeof value === "string") return value;
	if (typeof value === "number" || typeof value === "boolean")
		return String(value);
	return stringify(value);
}

const Section: FC<{
	title: string;
	meta?: string;
	children: ReactNode;
	className?: string;
}> = ({ title, meta, children, className }) => (
	<section className={cn(FILLED_BOX, "overflow-hidden", className)}>
		<header className="flex flex-wrap items-center justify-between gap-2 border-border/70 border-b px-3 py-2">
			<h2 className="font-medium text-sm">{title}</h2>
			{meta ? (
				<span className="text-muted-foreground text-xs">{meta}</span>
			) : null}
		</header>
		<div className="p-3">{children}</div>
	</section>
);

const LinkValue: FC<{ value: string; openLink: (href: string) => void }> = ({
	value,
	openLink,
}) => {
	if (!isExternalHttpUrl(value))
		return <span className="break-words">{value}</span>;
	let label = value;
	try {
		const url = new URL(value);
		label = `${url.host}${url.pathname === "/" ? "" : url.pathname}`;
	} catch {
		// isExternalHttpUrl already validated it; retain the full value on an edge case.
	}
	return (
		<Button
			type="button"
			variant="ghost"
			size="sm"
			className="h-auto max-w-full justify-start px-1 py-0 text-left font-normal text-xs"
			onClick={() => openLink(value)}
		>
			<ExternalLink className="mr-1 h-3 w-3 shrink-0" />
			<span className="truncate">{label}</span>
		</Button>
	);
};

function looksLikeEvent(value: UnknownRecord): boolean {
	return (
		("semantic_type" in value || "payload_type" in value) &&
		("id" in value ||
			"title" in value ||
			"payload_text" in value ||
			"content" in value)
	);
}

function looksLikeEntity(value: UnknownRecord): boolean {
	return (
		"id" in value &&
		typeof value.name === "string" &&
		("entity_type" in value || "entity_type_name" in value || "type" in value)
	);
}

const EventView: FC<{
	event: UnknownRecord;
	openLink: (href: string) => void;
}> = ({ event, openLink }) => {
	const title =
		typeof event.title === "string"
			? event.title
			: humanize(String(event.semantic_type ?? "Event"));
	const payloadType = String(event.payload_type ?? "text");
	const text =
		typeof event.payload_text === "string"
			? event.payload_text
			: typeof event.content === "string"
				? event.content
				: "";
	const sourceUrl =
		typeof event.source_url === "string" ? event.source_url : null;
	const template = isRecord(event.payload_template)
		? event.payload_template
		: null;
	const data = isRecord(event.payload_data) ? event.payload_data : {};
	const attachments = Array.isArray(event.attachments) ? event.attachments : [];
	const metadata = isRecord(event.metadata) ? event.metadata : null;

	return (
		<article className="rounded-md border border-border/70 bg-background/40 p-2.5">
			<div className="flex flex-wrap items-start justify-between gap-2">
				<div>
					<h3 className="font-medium text-sm">{title}</h3>
					<div className="text-muted-foreground text-[11px]">
						{humanize(String(event.semantic_type ?? "event"))}
						{event.id !== undefined ? ` · #${String(event.id)}` : ""}
					</div>
				</div>
				{sourceUrl && isExternalHttpUrl(sourceUrl) ? (
					<Button
						type="button"
						variant="ghost"
						size="sm"
						onClick={() => openLink(sourceUrl)}
					>
						<ExternalLink className="mr-1 h-3.5 w-3.5" />
						Source
					</Button>
				) : null}
			</div>
			<div className="mt-2">
				{payloadType === "json_template" && isRecord(template?.root) ? (
					<McpJsonTemplateView
						template={{ root: template.root as McpJsonNode }}
						data={data}
						openLink={openLink}
						actions={
							sourceUrl && isExternalHttpUrl(sourceUrl)
								? {
										openSource: () => openLink(sourceUrl),
										open_source: () => openLink(sourceUrl),
									}
								: undefined
						}
					/>
				) : payloadType === "markdown" && text ? (
					<McpMarkdownText text={text} openLink={openLink} />
				) : text ? (
					<p className="whitespace-pre-wrap break-words text-sm">{text}</p>
				) : Object.keys(data).length > 0 ? (
					<ValueView value={data} openLink={openLink} depth={1} />
				) : (
					<p className="text-muted-foreground text-xs">No event payload.</p>
				)}
			</div>
			{attachments.length > 0 ||
			(metadata && Object.keys(metadata).length > 0) ? (
				<details className="mt-2 text-xs">
					<summary className="cursor-pointer text-muted-foreground">
						Attachments and metadata
					</summary>
					<div className="mt-2 space-y-2">
						{attachments.length > 0 ? (
							<ValueView value={attachments} openLink={openLink} depth={1} />
						) : null}
						{metadata && Object.keys(metadata).length > 0 ? (
							<ValueView value={metadata} openLink={openLink} depth={1} />
						) : null}
					</div>
				</details>
			) : null}
		</article>
	);
};

const EntityView: FC<{
	entity: UnknownRecord;
	openLink: (href: string) => void;
}> = ({ entity, openLink }) => {
	const label = humanize(
		String(
			entity.entity_type ?? entity.entity_type_name ?? entity.type ?? "Entity",
		),
	);
	const metadata = isRecord(entity.metadata) ? entity.metadata : null;
	const link = [entity.view_url, entity.url, entity.source_url].find(
		isExternalHttpUrl,
	);
	return (
		<article className="rounded-md border border-border/70 bg-background/40 p-2.5">
			<div className="flex items-start justify-between gap-2">
				<div>
					<div className="font-mono text-[10px] uppercase tracking-wide text-muted-foreground">
						{label}
					</div>
					<h3 className="font-medium text-sm">{String(entity.name)}</h3>
					<div className="text-muted-foreground text-[11px]">
						#{String(entity.id)}
					</div>
				</div>
				{link ? (
					<Button
						type="button"
						variant="ghost"
						size="sm"
						onClick={() => openLink(link)}
					>
						<ExternalLink className="mr-1 h-3.5 w-3.5" />
						Open
					</Button>
				) : null}
			</div>
			{metadata && Object.keys(metadata).length > 0 ? (
				<div className="mt-2">
					<ValueView value={metadata} openLink={openLink} depth={1} />
				</div>
			) : null}
		</article>
	);
};

const ValueView: FC<{
	value: unknown;
	openLink: (href: string) => void;
	depth?: number;
}> = ({ value, openLink, depth = 0 }) => {
	if (typeof value === "string")
		return <LinkValue value={value} openLink={openLink} />;
	if (value === null || value === undefined || typeof value !== "object") {
		return <span className="break-words text-sm">{compactValue(value)}</span>;
	}
	if (depth >= 5) {
		return (
			<pre className="overflow-x-auto whitespace-pre-wrap text-xs">
				{stringify(value)}
			</pre>
		);
	}
	if (Array.isArray(value)) {
		if (value.length === 0)
			return <span className="text-muted-foreground text-xs">Empty</span>;
		const records = value.filter(isRecord);
		if (
			records.length === value.length &&
			!records.some(
				(record) => looksLikeEvent(record) || looksLikeEntity(record),
			)
		) {
			return <DataTable rows={records} openLink={openLink} />;
		}
		return (
			<div className="space-y-2">
				{value.slice(0, 100).map((item, index) => (
					// biome-ignore lint/suspicious/noArrayIndexKey: arbitrary result arrays may contain duplicate, identity-less values and are immutable here.
					<div key={`${index}:${compactValue(item).slice(0, 30)}`}>
						<ValueView value={item} openLink={openLink} depth={depth + 1} />
					</div>
				))}
				{value.length > 100 ? (
					<p className="text-muted-foreground text-xs">
						{value.length - 100} more items
					</p>
				) : null}
			</div>
		);
	}
	if (!isRecord(value))
		return <span className="text-sm">Unsupported value</span>;
	if (looksLikeEvent(value))
		return <EventView event={value} openLink={openLink} />;
	if (looksLikeEntity(value))
		return <EntityView entity={value} openLink={openLink} />;
	return (
		<dl className="grid gap-1.5">
			{Object.entries(value).map(([key, inner]) => (
				<div
					key={key}
					className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-2 text-xs"
				>
					<dt className="break-words font-medium text-muted-foreground">
						{humanize(key)}
					</dt>
					<dd className="min-w-0">
						<ValueView value={inner} openLink={openLink} depth={depth + 1} />
					</dd>
				</div>
			))}
		</dl>
	);
};

