};
const MAX_CHART_DIMENSION = 800;

function boundedDimension(
	value: number | undefined,
	fallback: number,
	minimum: number,
): number {
	const numeric = Number(value);
	return Math.max(
		minimum,
		Math.min(
			Number.isFinite(numeric) && numeric > 0 ? numeric : fallback,
			MAX_CHART_DIMENSION,
		),
	);
}

function seriesColor(key: string, index: number): string {
	return (
		PLATFORM_COLORS[key.toLowerCase()] ??
		CHART_COLORS[index % CHART_COLORS.length]
	);
}

/** Keep agent-authored chart paint values inert. SVG `fill="url(...)"` can make
 * a real network request even in an `allow-scripts` sandbox, so accept ordinary
 * CSS colors only and fall back to the built-in palette for everything else. */
function safeSvgPaint(value: unknown, fallback: string): string {
	if (typeof value !== "string") return fallback;
	const paint = value.trim();
	if (!paint || paint.length > 128 || /url\s*\(|[;{}<>@]/i.test(paint)) {
		return fallback;
	}
	if (/^#[\da-f]{3,8}$/i.test(paint)) return paint;
	if (/^(?:transparent|currentcolor|none|[a-z]+)$/i.test(paint)) return paint;
	if (
		/^(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch)\([-+.,%/\s\da-z]+\)$/i.test(paint)
	) {
		return paint;
	}
	return fallback;
}

