import { Check, ExternalLink, ShieldAlert, X } from "lucide-react";
import type { FC } from "react";
import { useEffect, useState } from "react";
import { DynamicConnectorForm } from "@/components/entity-tabs/connections-tab/dynamic-connector-form";
import { Button } from "@/components/ui/button";
import { Spinner } from "@/components/ui/spinner";
import { cn, FILLED_BOX } from "@/lib/utils";

/**
 * One data-driven renderer for every interactive agent interaction. The host
 * (or, later, the server) describes the card as a JSON view — `{title, blocks,
 * actions}` — and this component renders it; there is no per-interaction
 * component or bundle. A button posts its `{tool, args}` back through the MCP
 * App bridge for the host to broker. Adding an interaction type is a new view
 * shape, not new UI.
 */

export type InteractionBlock =
	| { type: "text"; label?: string; value: string; muted?: boolean }
	| { type: "code"; value: string }
	| {
			type: "form";
			schema: Record<string, unknown>;
			initialValues?: Record<string, unknown>;
			/** Backward-compatible alias used by existing SPA-authored views. */
			values?: Record<string, unknown>;
	  }
	| {
			type: "entity";
			id: string;
			label: string;
			name: string;
			details?: string[];
			recordLink?: InteractionAction;
			sourceLinks?: InteractionAction[];
	  }
	| {
			type: "diff";
			fields: { label: string; before?: string; after: string }[];
	  };

type InteractionActionBase = {
	/** Stable id (also the pending/resolved key). */
	id: string;
	label: string;
	variant?: "primary" | "outline" | "ghost" | "destructive";
	icon?: "check" | "external" | "x";
	/** Require a second click (Confirm/Cancel) before firing. */
	confirm?: boolean;
	confirmPrompt?: string;
	/** Default true. `false` = fire-and-forget (e.g. open a link), no lifecycle. */
	terminal?: boolean;
	/** Message shown once this action resolves. */
	resolvedLabel?: string;
	/** Merge the current schema-form values into this named tool argument. */
	submitFormAs?: string;
};

export type InteractionAction = InteractionActionBase &
	(
		| {
				/** MCP tool the host brokers, plus non-sensitive args. */
				tool: string;
				args?: Record<string, unknown>;
				href?: never;
		  }
		| {
				/** External URL the MCP Apps host opens through `ui/open-link`. */
				href: string;
				tool?: never;
				args?: never;
		  }
	);

export type InteractionView = {
	version?: 1;
	title?: string;
	/** `warning` = amber card (approvals/grants); `default` = filled box
	 *  (questions); `bare` = just the buttons (links). */
	tone?: "warning" | "default" | "bare";
	blocks?: InteractionBlock[];
	actions?: InteractionAction[];
};

const EMPTY_BLOCKS: InteractionBlock[] = [];

function isToolAction(
	action: InteractionAction,
): action is Extract<InteractionAction, { tool: string }> {
	return typeof action.tool === "string";
}

function initialFormValues(
	blocks: InteractionBlock[],
): Record<string, unknown> {
	const form = blocks.find((block) => block.type === "form");
	if (!form || form.type !== "form") return {};
	const properties =
		typeof form.schema.properties === "object" && form.schema.properties
			? (form.schema.properties as Record<string, Record<string, unknown>>)
			: {};
	const defaults = Object.fromEntries(
		Object.entries(properties)
			.filter(
				([, schema]) =>
					schema.default !== undefined || schema.type === "boolean",
			)
			.map(([name, schema]) => [
				name,
				schema.default !== undefined ? schema.default : false,
			]),
	);
	return { ...defaults, ...(form.initialValues ?? form.values ?? {}) };
}

const VARIANT: Record<
	NonNullable<InteractionAction["variant"]>,
	"default" | "outline" | "ghost" | "destructive"
> = {
	primary: "default",
	outline: "outline",
	ghost: "ghost",
	destructive: "destructive",
};

const ICON = { check: Check, external: ExternalLink, x: X };

function diffValue(value: string): string {
	return value === "" ? '""' : value;
}

/** Content-derived, index-free key for a block (blocks are never reordered). */
function blockKey(b: InteractionBlock): string {
	if (b.type === "diff")
		return `diff:${b.fields.map((f) => f.label).join(",")}`;
	if (b.type === "entity") return `entity:${b.id}`;
	if (b.type === "form")
		return `form:${Object.keys((b.schema.properties as object | undefined) ?? {}).join(",")}`;
	return `${b.type}:${b.value.slice(0, 32)}`;
}

const BlockView: FC<{
	block: InteractionBlock;
	onAction: (action: InteractionAction) => void;
	onFormValuesChange: (values: Record<string, unknown>) => void;
	disabled: boolean;
}> = ({ block, onAction, onFormValuesChange, disabled }) => {
	if (block.type === "text")
		return (
			<div>
				{block.label ? (
					<div className="font-medium text-foreground text-xs">
						{block.label}
					</div>
				) : null}
				<p
					className={cn(
						"whitespace-pre-line",
						block.muted ? "mt-1 text-xs text-muted-foreground" : "text-sm",
					)}
				>
					{block.value}
				</p>
			</div>
		);
	if (block.type === "code")
		return (
			<pre className="whitespace-pre-wrap break-words text-xs text-foreground/80">
				{block.value}
			</pre>
		);
	if (block.type === "form")
		return (
			<DynamicConnectorForm
				schema={block.schema}
				initialValues={block.initialValues ?? block.values}
				onValuesChange={onFormValuesChange}
				onOpenLink={(href) =>
					onAction({
						id: `form-link:${href}`,
						label: "Open link",
						href,
						terminal: false,
					})
				}
				fieldIdPrefix="mcp-approval-"
				readOnly={disabled}
			/>
		);
	if (block.type === "entity") {
		const recordLink = block.recordLink;
		const sourceLinks = block.sourceLinks ?? [];
		return (
			<div className="rounded-md border border-border/70 bg-background/35 px-2.5 py-2">
				<div className="font-mono text-[10px] uppercase tracking-wide text-muted-foreground">
					{block.label}
				</div>
				<div className="mt-0.5 flex flex-wrap items-center justify-between gap-1.5">
					<span className="break-words font-medium text-sm">{block.name}</span>
					{recordLink ? (
						<Button
							type="button"
							size="sm"
							variant="ghost"
							className="h-7 px-2"
							disabled={disabled}
							aria-label={`Open ${block.label.toLowerCase()} record ${block.name}`}
							onClick={() => onAction(recordLink)}
						>
							<ExternalLink className="mr-1 h-3.5 w-3.5" />
							{recordLink.label}
						</Button>
					) : null}
				</div>
				{block.details?.map((detail) => (
					<div
						key={detail}
						className="mt-1 break-words text-muted-foreground text-xs"
					>
						{detail}
					</div>
				))}
				{sourceLinks.length > 0 ? (
					<div className="mt-1 flex flex-wrap gap-1">
						{sourceLinks.map((link) => (
							<Button
								key={link.id}
								type="button"
								size="sm"
								variant="ghost"
								className="h-7 px-2"
								disabled={disabled}
								aria-label={`${link.label} for ${block.label.toLowerCase()} record ${block.name}`}
								onClick={() => onAction(link)}
							>
								<ExternalLink className="mr-1 h-3.5 w-3.5" />
								{link.label}
							</Button>
						))}
					</div>
				) : null}
			</div>
		);
	}
	return (
		<div className="space-y-1.5">
			{block.fields.map((f) => (
				<div key={f.label}>
					<div className="font-mono text-[10px] uppercase tracking-wide text-muted-foreground">
						{f.label}
					</div>
					{f.before !== undefined ? (
						<div className="grid grid-cols-1 gap-0.5">
							<span className="break-words text-red-700 line-through dark:text-red-400">
								{diffValue(f.before)}
							</span>
							<span className="break-words text-green-700 dark:text-green-400">
								{diffValue(f.after)}
							</span>
						</div>
					) : (
						<span className="break-words text-green-700 dark:text-green-400">
							{diffValue(f.after)}
						</span>
					)}
				</div>
			))}
		</div>
	);
};

export const InteractionCard: FC<{
	view: InteractionView;
	onAction: (action: InteractionAction) => void;
	pendingId?: string | null;
	resolvedId?: string | null;
}> = ({ view, onAction, pendingId = null, resolvedId = null }) => {
	const [confirmingId, setConfirmingId] = useState<string | null>(null);
	const tone = view.tone ?? "default";
	const actions = view.actions ?? [];
	const blocks = view.blocks ?? EMPTY_BLOCKS;
	const [formValues, setFormValues] = useState<Record<string, unknown>>(() =>
		initialFormValues(blocks),
	);
	const pending = pendingId !== null;

	useEffect(() => {
		setFormValues(initialFormValues(blocks));
	}, [blocks]);

	if (resolvedId) {
		const resolved = actions.find((a) => a.id === resolvedId);
		return (
			<div
				className={cn(FILLED_BOX, "px-3 py-2 text-xs text-muted-foreground")}
			>
				{resolved?.resolvedLabel ?? "Done."}
			</div>
		);
	}

	const confirming = confirmingId
		? actions.find((a) => a.id === confirmingId)
		: null;
	const submitAction = (action: InteractionAction) => {
		if (!action.submitFormAs || !isToolAction(action)) {
			onAction(action);
			return;
		}
		onAction({
			...action,
			args: {
				...(action.args ?? {}),
				[action.submitFormAs]: formValues,
			},
		});
	};

	const actionRow = confirming ? (
		<div className="flex items-center gap-1.5">
			<span className="mr-1 text-muted-foreground">
				{confirming.confirmPrompt ?? "Are you sure?"}
			</span>
			<Button
				type="button"
				size="sm"
				variant="destructive"
				disabled={pending}
				onClick={() => submitAction(confirming)}
			>
				{pendingId === confirming.id ? (
					<Spinner size="lg" className="mr-1" />
				) : null}
				Confirm
			</Button>
			<Button
				type="button"
				size="sm"
				variant="outline"
				disabled={pending}
				onClick={() => setConfirmingId(null)}
			>
				Cancel
			</Button>
		</div>
	) : (
		<div className="flex flex-wrap items-center gap-1.5">
			{actions.map((a) => {
				const Icon = a.icon ? ICON[a.icon] : null;
				return (
					<Button
						key={a.id}
						type="button"
						size="sm"
						variant={VARIANT[a.variant ?? "outline"]}
						disabled={pending}
						onClick={() =>
							a.confirm ? setConfirmingId(a.id) : submitAction(a)
						}
					>
						{pendingId === a.id ? (
							<Spinner size="lg" className="mr-1" />
						) : Icon ? (
							<Icon className="mr-1 h-3.5 w-3.5" />
						) : null}
						{a.label}
					</Button>
				);
			})}
		</div>
	);

	if (tone === "bare") return actionRow;

	const container =
		tone === "warning"
			? "rounded-lg border border-amber-500/40 bg-amber-500/10 px-3 py-2.5 text-xs"
			: cn(FILLED_BOX, "px-3 py-2");

	return (
		<div className={container}>
			{view.title ? (
				<div className="mb-2 flex items-center gap-1.5 font-medium">
					{tone === "warning" ? (
						<ShieldAlert className="h-3.5 w-3.5 text-amber-600 dark:text-amber-500" />
					) : null}
					<span>{view.title}</span>
				</div>
			) : null}
			{blocks.length > 0 ? (
				<div className="mb-2 space-y-2">
					{blocks.map((b) => (
						<BlockView
							key={blockKey(b)}
							block={b}
							onAction={onAction}
							onFormValuesChange={setFormValues}
							disabled={pending}
						/>
					))}
				</div>
			) : null}
			{actions.length > 0 ? actionRow : null}
		</div>
	);
};

